function drawSupport(){ctx.save();const orbs=supportFind('orbs');if(orbs){const n=Math.min(orbs.v('count'),Math.floor((orbs.b.elapsed+1e-8)/15));for(let i=0;i<n;i++){const a=supportState.clock*2+i*Math.PI*2/Math.max(1,n);ellipse(player.x+Math.cos(a)*30,player.y-35+Math.sin(a)*12,4,4,'#f3d783')}}const shield=supportFind('shield');if(shield&&shield.b.charges>0){ctx.strokeStyle='#b3dbef';ctx.lineWidth=2;ctx.beginPath();ctx.arc(player.x,player.y-25,34,0,Math.PI*2);ctx.stroke()}if(supportFind('invincible')){ctx.globalAlpha=.35;ellipse(player.x,player.y-25,30,40,'#fff4be')}ctx.restore()}

const supportPerform=performActiveSkill;
performActiveSkill=function(d,target){const oldProjectiles=new Set(activeProjectiles),oldFields=new Set(activeFields),oldSummons=new Set(activeSummons),oldBuffs={...player.activeBuffs};supportPerform(d,target);for(const p of activeProjectiles)if(!oldProjectiles.has(p)&&p.type==='rolling')p.life*=1+supportSum('fieldDuration')/100;for(const f of activeFields)if(!oldFields.has(f)&&f.type==='spiral'){f.life*=1+supportSum('fieldDuration')/100;f.duration=f.life}for(const summon of activeSummons)if(!oldSummons.has(summon)){summon.life*=1+supportSum('summon','duration')/100;summon.range*=1+supportSum('search')/100}for(const key in player.activeBuffs)if(player.activeBuffs[key]!==oldBuffs[key])player.activeBuffs[key]*=1+supportSum('buffDuration')/100;if(activeDash)activeDash.cap+=supportSum('mobCap','count')};
function supportMovementFactor(){if(player.charge?.baseImmobile&&supportFind('walkCharge'))return supportSum('walkCharge')/100;if(!player.charge&&!player.activeChannel&&!activeDash&&player.cd.action>0&&supportState.clock-supportState.memory.lastCast<.6)return supportFind('walkAttack')?supportSum('walkAttack')/100:0;return 1}

